int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t size, int msg_flags) {
    int ret;
    struct sock *sk = sock->sk;

    if (unlikely(!sk))
        return -EINVAL;

    if (unlikely(size > INT_MAX))
        size = INT_MAX;

    if (msg_flags & MSG_OOB)
        ret = sk->sk_prot->recvmsg(sk, msg, size, msg_flags, NULL, NULL);
    else
        ret = sk->sk_prot->recvmsg(sk, msg, size, msg_flags, NULL, NULL);

    if (ret > 0) {
        sock_update_net_families(sk);
        net_INC_STATS(sock_net(sk), LINUX_MIB_RECVMSGBYTES, ret);
    }

    return ret;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t size, int msg_flags) {
    int ret;
    struct sock *sk = sock->sk;

    if (sock->ops->recvmsg == NULL)
        return -EOPNOTSUPP;

    if (msg_flags & MSG_OOB)
        sk->ooo_is_set = 1;

    if (sk->sk_state == TCP_LISTEN)
        return -EOPNOTSUPP;

    ret = sk->sk_type == SOCK_DGRAM ? sock->ops->recvmsg(iocb, sock, msg, size, msg_flags) :
                                       sock->ops->recvmsg(iocb, sock, msg, size, msg_flags);

    if (ret > 0) {
        sk->sk_data_processed += ret;
        netdev_update_stats(sk->sk_netdev);
    }

    return ret;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int msg_flags) {
    int bytes_received;
    int result;
    unsigned int flags = 0;

    if (msg_flags & MSG_DONTWAIT)
        flags |= O_NONBLOCK;

    do {
        result = sock->ops->recvmsg(iocb, sock, msg, size, flags);
        if (result > 0) {
            msg->msg_flags = msg_flags;
            bytes_received = result;
            break;
        } else if (result == -EAGAIN) {
            if (msg_flags & MSG_DONTWAIT) {
                return -EAGAIN;
            }
            schedule_timeout_unordered(HZ / 10);
        } else if (result < 0) {
            return result;
        }
    } while (1);

    sock_update_stats(sock, bytes_received);
    return bytes_received;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int msg_flags) {
    int ret = 0;
    struct sock *sk = sock->sk;

    while (1) {
        ret = sk->ops->recvmsg(iocb, sock, msg, size, msg_flags);
        if (ret > 0) {
            sock_update_stats(sk, ret);
            return ret;
        }

        if (ret != -EAGAIN && ret != -EINTR) {
            return ret;
        }

        if (wait_for_pending_notification(sk)) {
            continue;
        }

        if (check_for_incoming_messages(sk)) {
            continue;
        }

        if (has_timeout_occurred(sk)) {
            return -ETIMEDOUT;
        }
    }
}
